"""Serialize manually authored SA04 research judgments.

All source passages were read before these records were composed. The only automatic
source operation is line-range lookup from scanpage markers. No verdict, mathematical
status, attribution, literature class, or merge is inferred from a keyword.
"""
from pathlib import Path
import json,re,csv,datetime
ROOT=Path(__file__).resolve().parents[2]
OUT=ROOT/'SA04_work/parts/root';OUT.mkdir(parents=True,exist_ok=True)
items=[];claims=[];problems=[];readings=[];links=[];events=[]
WHO='GPT-6 Astra Pro; effort not exposed; SA04 root'
DAY='2026-11-19'
def loc(file,scans,cote=None):
    p=ROOT/'source/SA04_texts'/file
    ls=p.read_text().splitlines(); marks=[]; current_cote=None
    for i,l in enumerate(ls,1):
        c=re.search(r'\\cotefile\{([^}]+)\}',l)
        if c:current_cote=c[1]
        m=re.search(r'\\scanpage\{(\d+)\}',l)
        if m:marks.append((int(m[1]),i,current_cote))
    ans=[]
    for j,(n,a,c) in enumerate(marks):
        if n in scans and (cote is None or c==str(cote)):
            ans.append((a,marks[j+1][1]-1 if j+1<len(marks) else len(ls)))
    assert ans,(file,scans)
    return [file+':'+str(a)+'–'+str(b) for a,b in ans]
def K(n):return f'codex/K93-{n:02d}_transcription.tex'
P100='pro/MPL_8_079-081+9+4+100_transcription.tex'
def I(n,cote,scans,file,kind,words,statement,reconstruction='',check='agrees',reason=''):
    d=dict(id=f'SA04-{n}',sources=[],kind=kind,cote=str(cote),scans=scans,lines=loc(file,scans,cote),his_words=words,statement=statement,reconstruction=reconstruction or 'Modern wording is supplied by this audit; the attribution, qualifications, and cancellations remain those of the cited transcription.',check=check,check_reason=reason or 'Read directly in the transcription and compared with the unindexed Codex/Pro notes. This is an additional transcription-derived item, not a new row of NOTES_INDEX.')
    items.append(d);events.append([d['id'],DAY,WHO,'used and rechecked in this run','Textual comparison only; no proof certification is implied. '+d['check_reason']]);return n
def C(n,item,statement,status,cl,fate,refs=(),computation='',confidence='high',present='',date='',words=None):
    it=next(x for x in items if x['id']==f'SA04-{item}')
    d=dict(id=f'C-SA04-{n}',items=[it['id']],cote=it['cote'],scans=it['scans'],lines=it['lines'],his_statement=words or it['his_words'],statement=statement,status_on_pages=status,computation=computation or 'No numerical computation is used. The cited passage and the mathematical scope of its construction were checked; this is not an independent proof of the whole claim.',**{'class':cl},fate=fate,fate_date=date or 'Manuscript layer undated. Dates of checked editions are in the bibliography; first circulation is not established unless specified.',present_status='As of 19 November 2026: '+(present or statement),refs=list(refs),confidence=confidence)
    claims.append(d);events.append([d['id'],DAY,WHO,'used and rechecked in this run','Checked source formulation, attribution, hypotheses and cited literature match; independent proof status is given separately in computation and proof-check records.'])
def P(n,title,ids,as_he,plausible,art,why,worth,refs=()):
    cs=[x for x in claims if x['id'] in [f'C-SA04-{i}' for i in ids]]
    problems.append(dict(id=f'MP-SA04-{n:02d}',title=title,occurrences=[dict(claim=x['id'],cote=x['cote'],scans=x['scans'],lines=x['lines']) for x in cs],as_he_states=as_he,plausible_today=plausible,state_of_art=art,why_open=why,worth=worth,refs=list(refs)))
def R(cote,scan,line,reading,alternative,evidence,weight='high',confidence='high'):
    readings.append([str(cote),str(scan),line,reading,alternative,evidence,weight,confidence])

