def save():
    for name,data in [('items',items),('claims',claims),('problems',problems)]:
        (OUT/(name+'.json')).write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
    for name,header,data in [('readings',['cote','scan','line','reading','alternative','evidence','weight','confidence'],readings),('links',['kind','from','to','what','evidence','note_ids'],links),('CHECK_EVENTS',['statement_id','date','who','type','outcome'],events)]:
        with (OUT/(name+'.tsv')).open('w',newline='') as f:
            w=csv.writer(f,delimiter='\t');w.writerow(header);w.writerows(data)
    out={'items':len(items),'claims':len(claims),'problems':len(problems),'readings':len(readings),'links':len(links),'events':len(events)}
    print(json.dumps(out));(ROOT/'SA04_work/outputs/root_build.json').write_text(json.dumps(out,indent=2)+'\n')
    with (ROOT/'SA04_work/progress.log').open('a') as f:f.write(datetime.datetime.now(datetime.timezone.utc).isoformat()+'\troot_build.py\t'+json.dumps(out)+'\n')
if __name__=='__main__':save()
